                break
            if word1[end1-i] == word2[end2-i]:
                count += 1
        return count
    count = 0
    for i in range(len(strings)):
        for j in range(i + 1, len(strings)):
            c_suffix = match_ends(strings[i], strings[j])
            if c_suffix > count:
                count = c_suffix
    return count
